# Generated by Django to separate Didactique (Q1-Q60) and Sciences de l'Education (Q61+) for 2022-2025

from django.db import migrations
import re

def separate_didactique_and_sciences_edu(apps, schema_editor):
    Question = apps.get_model('exams', 'Question')

    # Get all questions currently under DIDACTIQUE for 2022-2025
    didactique_questions = Question.objects.filter(
        exam_year__in=[2022, 2023, 2024, 2025],
        domain_id='DIDACTIQUE'
    )

    reclassified_count = 0
    for q in didactique_questions:
        qn = q.question_number or ''
        digits = re.findall(r'\d+', qn)
        if digits:
            num = int(digits[0])
            if num > 60:
                q.domain_id = 'SCIENCES_EDU'
                q.subdomain_id = 'EDU_SOCIO'
                q.course_id = 26
                q.save(update_fields=['domain', 'subdomain', 'course'])
                reclassified_count += 1

    print(f"Migration: successfully reclassified {reclassified_count} questions to SCIENCES_EDU")

def reverse_separation(apps, schema_editor):
    pass

class Migration(migrations.Migration):

    dependencies = [
        ('exams', '0029_format_2022_q31_algorithm'),
    ]

    operations = [
        migrations.RunPython(separate_didactique_and_sciences_edu, reverse_code=reverse_separation),
    ]
